// Sales-vertical strings (sr.* keys, ar/en/ur) merged into the same t()
// lookup — one provider, one switcher, no parallel i18n system. Urdu has
// sales keys only; everything else falls back to English via t().
const dicts: Record<Language, Record<string, string>> = {
  en: { ...translations.en, ...salesTranslations.en },
  ar: { ...translations.ar, ...salesTranslations.ar },
  ur: { ...salesTranslations.ur },
}

/**
 * Pure key lookup, independent of React. Exported so callers that have no provider —
 * chiefly component tests — can assert against the REAL strings instead of a stub that
 * echoes keys back and proves nothing. Unknown keys fall back to English, then to the
 * key itself, exactly as `t()` does.
 */
export function translate(key: string, lang: Language = 'ar'): string {
  return dicts[lang]?.[key] || dicts['en'][key] || key
}

interface I18nContextType {
  lang: Language
  setLang: (lang: Language) => void
  t: (key: string) => string
  dir: 'ltr' | 'rtl'
  isRTL: boolean
}

const I18nContext = createContext<I18nContextType | null>(null)

export function I18nProvider({ children }: { children: ReactNode }) {
  // Arabic-first: matches the SSR <html lang="ar" dir="rtl"> so the public (Arabic) site is never
  // reset to en/ltr after hydration. Users who explicitly switch to English persist it in
  // localStorage ('meena-lang') and that choice is restored on load below.
  const [lang, setLangState] = useState<Language>('ar')

  useEffect(() => {
    // Load saved language
    const saved = localStorage.getItem('meena-lang') as Language
    if (saved && (saved === 'en' || saved === 'ar' || saved === 'ur')) {
      setLangState(saved)
    }
  }, [])

  const setLang = useCallback(async (newLang: Language) => {
    // Optimistic UI update - update immediately without waiting for API
    setLangState(newLang)
    localStorage.setItem('meena-lang', newLang)
    document.documentElement.lang = newLang
    document.documentElement.dir = RTL_LANGS.includes(newLang) ? 'rtl' : 'ltr'

    // Sync to Frappe backend in background - handle errors gracefully
    try {
      const currentUser = await getCurrentUser()
      if (currentUser && currentUser !== 'Guest') {
        await frappeClient.call('frappe.client.set_value', {
          doctype: 'User',
          name: currentUser,
          fieldname: 'language',
          value: newLang, // 'ar' | 'en' | 'ur' — all exist as frappe Language records
        })
      }
    } catch (err) {
      console.debug('Failed to sync language to Frappe backend:', err)
    }
  }, [])

  // Set initial dir
  useEffect(() => {
    document.documentElement.lang = lang
    document.documentElement.dir = RTL_LANGS.includes(lang) ? 'rtl' : 'ltr'
  }, [lang])

  const t = useCallback((key: string): string => translate(key, lang), [lang])

  const dir = RTL_LANGS.includes(lang) ? 'rtl' : 'ltr'
  const isRTL = RTL_LANGS.includes(lang)

  return (
    <I18nContext.Provider value={{ lang, setLang, t, dir, isRTL }}>
      {children}
    </I18nContext.Provider>
  )
}

export function useI18n() {
  const context = useContext(I18nContext)
  if (!context) {
    throw new Error('useI18n must be used within an I18nProvider')
  }
  return context
}
